def import_repot_history(apps, schema_editor):
    Orchid = apps.get_model('orchids', 'Orchid')
    OrchidEvent = apps.get_model('orchids', 'OrchidEvent')

    for orchid in Orchid.objects.all().iterator():
        raw_dates = orchid.repot_dates or []
        if not isinstance(raw_dates, list):
            raw_dates = [raw_dates]
        for value in raw_dates:
            if isinstance(value, dict):
                value = value.get('date') or value.get('event_date') or value.get('repot_date')
            if not isinstance(value, str):
                continue
            try:
                event_date = date.fromisoformat(value[:10])
            except ValueError:
                continue
            OrchidEvent.objects.get_or_create(
                orchid_id=orchid.pk,
                event_type='repotting',
                event_date=event_date,
                defaults={'notes': 'Imported from previous repot history.'},
            )


